package services

// PhpMyAdminUserConfig is the generated phpMyAdmin configuration. The default
// authentication mode is signon: the dashboard issues a short-lived signed
// token, and signon.php exchanges it for a normal phpMyAdmin session. A direct
// visit without a token shows the manual signon form instead of logging in as
// root.
const PhpMyAdminUserConfig = `<?php
// Generated by devstack for token-based phpMyAdmin signon.
// This file is user-owned after the first install; devstack only migrates the
// exact generated legacy files and never overwrites operator edits.
$cfg['UploadDir'] = '';
$cfg['SaveDir'] = '';
$signonHost = $_SERVER['HTTP_HOST'] ?? '127.0.0.1:8082';
if (!preg_match('/^(?:127\.0\.0\.1|localhost|devstack\.test)(?::\d+)?$/', $signonHost)) {
    $signonHost = '127.0.0.1:8082';
}
$cfg['Servers'][1]['host'] = 'db';
$cfg['Servers'][1]['port'] = '3306';
$cfg['Servers'][1]['auth_type'] = 'signon';
$cfg['Servers'][1]['SignonSession'] = 'devstack_signon';
$cfg['Servers'][1]['SignonURL'] = 'http://' . $signonHost . '/signon.php';
$cfg['Servers'][1]['SignonCookieParams'] = [
    'lifetime' => 0,
    'path' => '/',
    'secure' => false,
    'httponly' => true,
    'samesite' => 'Strict',
];
$cfg['Servers'][1]['LogoutURL'] = 'http://' . $signonHost . '/signon.php';
`

// PhpMyAdminLegacyUserConfig is the exact cookie-auth file generated by early
// devstack versions. It is migrated in place so older installs do not keep an
// unauthenticated phpMyAdmin.
const PhpMyAdminLegacyUserConfig = `<?php
// Generated by devstack as a safe starting point.
// This file is user-owned after the first install; devstack never overwrites it.
// "db" is the fixed Compose network alias for the active MySQL-family service.
$cfg['UploadDir'] = '';
$cfg['SaveDir'] = '';
$cfg['Servers'][1]['host'] = 'db';
$cfg['Servers'][1]['port'] = '3306';
$cfg['Servers'][1]['auth_type'] = 'cookie';
`

// PhpMyAdminConfigAuthUserConfig is the exact config-auth file generated by the
// earlier auto-login implementation. It is migrated to signon because config
// auth gives every loopback visitor root access.
const PhpMyAdminConfigAuthUserConfig = `<?php
// Generated by devstack for automatic phpMyAdmin login.
// This file is user-owned after the first install; devstack only migrates the
// exact legacy generated file and never overwrites operator edits.
// "db" is the fixed Compose network alias for the active MySQL-family service.
$cfg['UploadDir'] = '';
$cfg['SaveDir'] = '';
$cfg['Servers'][1]['host'] = 'db';
$cfg['Servers'][1]['port'] = '3306';
$cfg['Servers'][1]['auth_type'] = 'config';
$cfg['Servers'][1]['user'] = 'root';
$cfg['Servers'][1]['password'] = trim((string) @file_get_contents('/run/secrets/root_password'));
$cfg['Servers'][1]['AllowNoPassword'] = false;
`
